const QUESTIONS=[
{id:"two-sum",topic:"Arrays",title:"Two Sum",difficulty:"Easy",description:"Given n integers and a target, print the zero-based indices of two distinct values whose sum is the target. Exactly one pair exists; print the smaller index first.",format:"Line 1: n target. Line 2: n integers. Output: two indices.",hint:"For each number, look for target − number among the values already visited.",approach:"One pass with a hash map. O(n) time, O(n) space.",tests:[{input:"4 9\n2 7 11 15\n",output:"0 1"},{input:"3 6\n3 2 4\n",output:"1 2"},{input:"2 6\n3 3\n",output:"0 1"}],solution:`import java.util.*;\nclass Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),t=s.nextInt();Map<Integer,Integer>m=new HashMap<>();for(int i=0;i<n;i++){int v=s.nextInt(),c=t-v;if(m.containsKey(c)){System.out.println(m.get(c)+" "+i);return;}m.put(v,i);}}}`},
{id:"max-subarray",topic:"Arrays",title:"Maximum Subarray",difficulty:"Medium",description:"Find the largest sum of any non-empty contiguous subarray of the given integer array.",format:"Line 1: n. Line 2: n integers. Output: maximum sum.",hint:"At each element, either extend the current subarray or start a new one.",approach:"Kadane’s algorithm. O(n) time, O(1) extra space.",tests:[{input:"9\n-2 1 -3 4 -1 2 1 -5 4\n",output:"6"},{input:"1\n5\n",output:"5"},{input:"4\n-8 -3 -6 -2\n",output:"-2"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();long c=s.nextLong(),b=c;for(int i=1;i<n;i++){long v=s.nextLong();c=Math.max(v,c+v);b=Math.max(b,c);}System.out.println(b);}}`},
{id:"contains-duplicate",topic:"Arrays",title:"Contains Duplicate",difficulty:"Easy",description:"Return true if any integer appears at least twice in the array; otherwise return false.",format:"Line 1: n. Line 2: n integers. Output: true or false.",hint:"Insert each value into a set; a failed insertion identifies a duplicate.",approach:"Hash set scan. O(n) average time and O(n) space.",tests:[{input:"4\n1 2 3 1\n",output:"true"},{input:"4\n1 2 3 4\n",output:"false"},{input:"3\n0 0 1\n",output:"true"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();Set<Integer>a=new HashSet<>();boolean d=false;for(int i=0;i<n;i++)if(!a.add(s.nextInt()))d=true;System.out.println(d);}}`},
{id:"valid-anagram",topic:"Strings",title:"Valid Anagram",difficulty:"Easy",description:"Given two lowercase English strings, determine whether one is an anagram of the other.",format:"Two strings. Output: true or false.",hint:"Anagrams have equal character counts; lengths must also match.",approach:"Count letters in one pass over both strings. O(n) time, O(1) space for 26 letters.",tests:[{input:"anagram nagaram\n",output:"true"},{input:"rat car\n",output:"false"},{input:"a a\n",output:"true"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);String a=s.next(),b=s.next();int[]c=new int[26];for(char v:a.toCharArray())c[v-'a']++;for(char v:b.toCharArray())c[v-'a']--;boolean ok=a.length()==b.length();for(int v:c)if(v!=0)ok=false;System.out.println(ok);}}`},
{id:"valid-palindrome",topic:"Strings",title:"Valid Palindrome",difficulty:"Easy",description:"Ignore spaces and punctuation and compare case-insensitively. Decide whether the remaining letters and digits read the same forward and backward.",format:"One full input line. Output: true or false.",hint:"Use two pointers; skip non-alphanumeric characters before comparing.",approach:"Two-pointer scan. O(n) time and O(1) extra space.",tests:[{input:"A man, a plan, a canal: Panama\n",output:"true"},{input:"race a car\n",output:"false"},{input:" \n",output:"true"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);String a=s.hasNextLine()?s.nextLine():"";int l=0,r=a.length()-1;boolean ok=true;while(l<r){while(l<r&&!Character.isLetterOrDigit(a.charAt(l)))l++;while(l<r&&!Character.isLetterOrDigit(a.charAt(r)))r--;if(Character.toLowerCase(a.charAt(l++))!=Character.toLowerCase(a.charAt(r--))){ok=false;break;}}System.out.println(ok);}}`},
{id:"binary-search",topic:"Binary Search",title:"Binary Search",difficulty:"Easy",description:"Find a target in a sorted integer array. Print its zero-based index, or -1 if it is absent.",format:"Line 1: n target. Line 2: n sorted integers. Output: index or -1.",hint:"Compare the middle value and discard the half that cannot contain the target.",approach:"Closed-interval binary search. O(log n) time and O(1) space.",tests:[{input:"6 9\n-1 0 3 5 9 12\n",output:"4"},{input:"4 2\n1 3 5 7\n",output:"-1"},{input:"1 5\n5\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),t=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();int l=0,r=n-1,z=-1;while(l<=r){int m=l+(r-l)/2;if(a[m]==t){z=m;break;}if(a[m]<t)l=m+1;else r=m-1;}System.out.println(z);}}`},
{id:"valid-parentheses",topic:"Stacks",title:"Valid Parentheses",difficulty:"Easy",description:"Determine whether a string of (), {}, and [] brackets is correctly matched and nested.",format:"One bracket string. Output: true or false.",hint:"The latest unmatched opening bracket must be the next one closed.",approach:"Use a stack and verify each closing bracket against its top. O(n) time, O(n) space.",tests:[{input:"()[]{}\n",output:"true"},{input:"(]\n",output:"false"},{input:"([{}])\n",output:"true"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);String a=s.hasNext()?s.next():"";Deque<Character>d=new ArrayDeque<>();boolean ok=true;for(char c:a.toCharArray()){if(c=='('||c=='['||c=='{')d.push(c);else{if(d.isEmpty()){ok=false;break;}char v=d.pop();if((c==')'&&v!='(')||(c==']'&&v!='[')||(c=='}'&&v!='{')){ok=false;break;}}}System.out.println(ok&&d.isEmpty());}}`},
{id:"climbing-stairs",topic:"Dynamic Programming",title:"Climbing Stairs",difficulty:"Easy",description:"You may climb 1 or 2 steps at a time. Given n, return the number of distinct ways to reach the top.",format:"One integer n. Output: number of ways.",hint:"Ways to reach step n equal ways(n−1) + ways(n−2).",approach:"Fibonacci recurrence using two rolling values. O(n) time, O(1) space.",tests:[{input:"2\n",output:"2"},{input:"3\n",output:"3"},{input:"1\n",output:"1"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();long a=1,b=1;for(int i=2;i<=n;i++){long c=a+b;a=b;b=c;}System.out.println(n==0?1:b);}}`},
{id:"best-time-stock",topic:"Arrays",title:"Best Time to Buy and Sell Stock",difficulty:"Easy",description:"Choose one day to buy and a later day to sell. Return the maximum profit; return 0 if no positive profit is possible.",format:"Line 1: n. Line 2: n prices. Output: maximum profit.",hint:"Keep the lowest price seen so far while scanning forward.",approach:"Single pass tracking minimum price and best profit. O(n) time, O(1) space.",tests:[{input:"6\n7 1 5 3 6 4\n",output:"5"},{input:"5\n7 6 4 3 1\n",output:"0"},{input:"1\n5\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),lo=Integer.MAX_VALUE,b=0;for(int i=0;i<n;i++){int v=s.nextInt();b=Math.max(b,v-lo);lo=Math.min(lo,v);}System.out.println(b);}}`},
{id:"first-unique",topic:"Strings",title:"First Unique Character",difficulty:"Easy",description:"Return the index of the first character that occurs exactly once in a lowercase string, or -1 if none exists.",format:"One lowercase string. Output: index or -1.",hint:"Count each letter, then scan the string again from left to right.",approach:"Two passes with a 26-element count array. O(n) time, O(1) space.",tests:[{input:"leetcode\n",output:"0"},{input:"loveleetcode\n",output:"2"},{input:"aabb\n",output:"-1"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);String a=s.next();int[]c=new int[26];for(char v:a.toCharArray())c[v-'a']++;int z=-1;for(int i=0;i<a.length();i++)if(c[a.charAt(i)-'a']==1){z=i;break;}System.out.println(z);}}`},
{id:"product-except-self",topic:"Arrays",title:"Product of Array Except Self",difficulty:"Medium",description:"For each index, output the product of every other array element. Do not use division.",format:"Line 1: n. Line 2: n integers. Output: n products.",hint:"Build prefix products, then multiply each by a running suffix product.",approach:"Two passes. O(n) time, O(1) extra space excluding the output array.",tests:[{input:"4\n1 2 3 4\n",output:"24 12 8 6"},{input:"3\n-1 1 0\n",output:"0 0 -1"},{input:"2\n3 5\n",output:"5 3"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();long[]a=new long[n],o=new long[n];for(int i=0;i<n;i++)a[i]=s.nextLong();long p=1;for(int i=0;i<n;i++){o[i]=p;p*=a[i];}p=1;for(int i=n-1;i>=0;i--){o[i]*=p;p*=a[i];}StringJoiner j=new StringJoiner(" ");for(long v:o)j.add(""+v);System.out.println(j);}}`},
{id:"daily-temperatures",topic:"Stacks",title:"Daily Temperatures",difficulty:"Medium",description:"For each day, report how many days until a warmer temperature. If no warmer day exists, report 0.",format:"Line 1: n. Line 2: n temperatures. Output: n wait counts.",hint:"Keep indices of days still waiting in a decreasing-temperature stack.",approach:"Monotonic stack. Each index is pushed/popped once: O(n) time, O(n) space.",tests:[{input:"8\n73 74 75 71 69 72 76 73\n",output:"1 1 4 2 1 1 0 0"},{input:"1\n30\n",output:"0"},{input:"4\n80 70 60 50\n",output:"0 0 0 0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n],o=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();Deque<Integer>d=new ArrayDeque<>();for(int i=0;i<n;i++){while(!d.isEmpty()&&a[i]>a[d.peek()]){int j=d.pop();o[j]=i-j;}d.push(i);}StringJoiner z=new StringJoiner(" ");for(int v:o)z.add(""+v);System.out.println(z);}}`},
{id:"majority-element",topic:"Arrays",title:"Majority Element",difficulty:"Easy",description:"Return the value that appears more than n/2 times. The input is guaranteed to contain such a value.",format:"Line 1: n. Line 2: n integers. Output: majority value.",hint:"Pair off different values; the majority candidate cannot be fully cancelled.",approach:"Boyer–Moore majority vote. O(n) time, O(1) space.",tests:[{input:"7\n2 2 1 1 1 2 2\n",output:"2"},{input:"3\n3 3 4\n",output:"3"},{input:"1\n-1\n",output:"-1"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),c=0,k=0;for(int i=0;i<n;i++){int v=s.nextInt();if(k==0)c=v;k+=v==c?1:-1;}System.out.println(c);}}`},
{id:"reverse-linked-list",topic:"Linked Lists",title:"Reverse Linked List",difficulty:"Easy",description:"Reverse a singly linked list and print its values in the new order. An empty list produces an empty output line.",format:"Line 1: n. Line 2: n node values. Output: reversed values separated by spaces.",hint:"Save the next pointer before reversing each link. Keep previous and current pointers.",approach:"Iterative pointer reversal. O(n) time and O(1) extra space.",tests:[{input:"5\n1 2 3 4 5\n",output:"5 4 3 2 1"},{input:"0\n",output:""},{input:"1\n7\n",output:"7"}],solution:`import java.util.*;class Node{int v;Node next;Node(int x){v=x;}}class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();Node h=null,t=null;for(int i=0;i<n;i++){Node a=new Node(s.nextInt());if(h==null)h=a;else t.next=a;t=a;}Node p=null,c=h;while(c!=null){Node z=c.next;c.next=p;p=c;c=z;}StringJoiner j=new StringJoiner(" ");while(p!=null){j.add(""+p.v);p=p.next;}System.out.println(j);}}`},
{id:"merge-sorted-arrays",topic:"Arrays",title:"Merge Two Sorted Arrays",difficulty:"Easy",description:"Merge two non-decreasing integer arrays into one sorted sequence.",format:"Line 1: n m. Line 2: n values. Line 3: m values. Output: merged values separated by spaces.",hint:"Keep one pointer in each array and append the smaller available value.",approach:"Two-pointer merge. O(n+m) time and O(n+m) output space.",tests:[{input:"3 3\n1 2 4\n1 3 4\n",output:"1 1 2 3 4 4"},{input:"0 2\n\n3 5\n",output:"3 5"},{input:"2 0\n-2 8\n\n",output:"-2 8"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),m=s.nextInt();int[]a=new int[n],b=new int[m];for(int i=0;i<n;i++)a[i]=s.nextInt();for(int i=0;i<m;i++)b[i]=s.nextInt();StringJoiner j=new StringJoiner(" ");int i=0,k=0;while(i<n||k<m){if(k==m||(i<n&&a[i]<=b[k]))j.add(""+a[i++]);else j.add(""+b[k++]);}System.out.println(j);}}`},
{id:"number-of-islands",topic:"Graphs",title:"Number of Islands",difficulty:"Medium",description:"Count groups of '1' cells in a binary grid. Cells are connected horizontally or vertically; diagonal contact does not connect islands.",format:"Line 1: n m. Next n lines: grid rows made of 0 and 1. Output: island count.",hint:"Each time an unvisited land cell appears, count one island and traverse its whole component.",approach:"DFS or BFS each component once. O(nm) time and O(nm) worst-case space.",tests:[{input:"4 5\n11000\n11000\n00100\n00011\n",output:"3"},{input:"1 1\n0\n",output:"0"},{input:"2 2\n11\n11\n",output:"1"}],solution:`import java.util.*;class Main{static void go(char[][]g,int r,int c){if(r<0||r==g.length||c<0||c==g[0].length||g[r][c]!='1')return;g[r][c]='0';go(g,r+1,c);go(g,r-1,c);go(g,r,c+1);go(g,r,c-1);}public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),m=s.nextInt(),k=0;char[][]g=new char[n][m];for(int i=0;i<n;i++)g[i]=s.next().toCharArray();for(int i=0;i<n;i++)for(int j=0;j<m;j++)if(g[i][j]=='1'){k++;go(g,i,j);}System.out.println(k);}}`},
{id:"queue-using-stacks",topic:"Queues",title:"Implement Queue Using Stacks",difficulty:"Easy",description:"Process queue commands in order: push x adds a value, pop removes and prints the front value, and front prints the front without removing it. Commands are valid.",format:"First line: q. Next q lines: push x, pop, or front. Print one value per pop/front command.",hint:"Use an input stack and output stack. Transfer elements only when the output stack is empty.",approach:"Each item moves between stacks at most once, giving amortized O(1) per command.",tests:[{input:"6\npush 1\npush 2\nfront\npop\nfront\npop\n",output:"1\n1\n2\n2"},{input:"3\npush -4\nfront\npop\n",output:"-4\n-4"},{input:"1\npush 9\n",output:""}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int q=s.nextInt();Deque<Integer>a=new ArrayDeque<>(),b=new ArrayDeque<>();StringBuilder o=new StringBuilder();while(q-->0){String c=s.next();if(c.equals("push"))a.push(s.nextInt());else{if(b.isEmpty())while(!a.isEmpty())b.push(a.pop());int v=b.peek();if(c.equals("pop"))b.pop();if(o.length()>0)o.append('\\n');o.append(v);}}System.out.print(o);}}`},
{id:"move-zeroes",topic:"Arrays",title:"Move Zeroes",difficulty:"Easy",description:"Move every zero to the end of the array while keeping the relative order of the non-zero values unchanged. Modify and print the array.",format:"Line 1: n. Line 2: n integers. Output: rearranged values.",hint:"Write each non-zero value forward, then fill the remaining positions with zero.",approach:"Stable two-pointer compaction. O(n) time and O(1) extra space.",tests:[{input:"5\n0 1 0 3 12\n",output:"1 3 12 0 0"},{input:"1\n0\n",output:"0"},{input:"4\n1 2 3 4\n",output:"1 2 3 4"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),j=0;int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();for(int v:a)if(v!=0)a[j++]=v;while(j<n)a[j++]=0;StringJoiner o=new StringJoiner(" ");for(int v:a)o.add(""+v);System.out.println(o);}}`},
{id:"missing-number",topic:"Arrays",title:"Missing Number",difficulty:"Easy",description:"An array contains n distinct values from the range 0 through n, with one value missing. Return the missing value.",format:"Line 1: n. Line 2: n distinct integers. Output: missing value.",hint:"Compare the expected sum from 0 to n with the sum of the input values.",approach:"Use the arithmetic-series sum or XOR. O(n) time, O(1) space.",tests:[{input:"3\n3 0 1\n",output:"2"},{input:"2\n0 1\n",output:"2"},{input:"1\n0\n",output:"1"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),v=n;for(int i=0;i<n;i++)v^=i^s.nextInt();System.out.println(v);}}`},
{id:"remove-duplicates",topic:"Arrays",title:"Remove Duplicates from Sorted Array",difficulty:"Easy",description:"Given a sorted array, remove duplicates in place so each distinct value appears once. Print the unique prefix length and then its values.",format:"Line 1: n. Line 2: n sorted integers. Output: k, then the first k unique values.",hint:"Keep a write index for the last unique value and advance it only when the value changes.",approach:"Two pointers over sorted input. O(n) time, O(1) extra space.",tests:[{input:"5\n1 1 2 2 3\n",output:"3\n1 2 3"},{input:"1\n4\n",output:"1\n4"},{input:"4\n1 2 3 4\n",output:"4\n1 2 3 4"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();int k=0;for(int v:a)if(k==0||a[k-1]!=v)a[k++]=v;System.out.println(k);for(int i=0;i<k;i++){if(i>0)System.out.print(" ");System.out.print(a[i]);}}}`},
{id:"longest-common-prefix",topic:"Strings",title:"Longest Common Prefix",difficulty:"Easy",description:"Find the longest prefix shared by all supplied strings. Print an empty line if they share no prefix.",format:"Line 1: n. Next n lines: one lowercase string each. Output: common prefix.",hint:"Start with the first string and shorten the candidate until every other string starts with it.",approach:"Compare characters across strings or shrink a prefix. O(total input characters) time.",tests:[{input:"3\nflower\nflow\nflight\n",output:"fl"},{input:"2\ndog\nracecar\n",output:""},{input:"1\nsolo\n",output:"solo"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();String p=s.next();for(int i=1;i<n;i++){String a=s.next();while(!a.startsWith(p))p=p.substring(0,p.length()-1);}System.out.println(p);}}`},
{id:"reverse-words",topic:"Strings",title:"Reverse Words in a String",difficulty:"Medium",description:"Reverse the order of words in a line. Collapse repeated spaces and do not include leading or trailing spaces in the output.",format:"One full input line. Output: words in reverse order separated by one space.",hint:"Split on whitespace, discard empty pieces, and join the remaining words from right to left.",approach:"Tokenize once and reverse the tokens. O(n) time and O(n) output space.",tests:[{input:"the sky is blue\n",output:"blue is sky the"},{input:"  hello world  \n",output:"world hello"},{input:"one\n",output:"one"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);String a=s.hasNextLine()?s.nextLine().trim():"";if(a.isEmpty()){System.out.println("");return;}String[]w=a.split("\\\\s+");Collections.reverse(Arrays.asList(w));System.out.println(String.join(" ",w));}}`},
{id:"house-robber",topic:"Dynamic Programming",title:"House Robber",difficulty:"Medium",description:"Each house has a non-negative amount of money. Choose houses so no two adjacent houses are robbed, and maximize the total.",format:"Line 1: n. Line 2: n amounts. Output: maximum amount.",hint:"For each house, compare skipping it with taking it plus the best result two houses back.",approach:"Rolling dynamic programming. O(n) time and O(1) space.",tests:[{input:"4\n1 2 3 1\n",output:"4"},{input:"5\n2 7 9 3 1\n",output:"12"},{input:"1\n5\n",output:"5"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();long two=0,one=0;for(int i=0;i<n;i++){long v=s.nextLong(),cur=Math.max(one,two+v);two=one;one=cur;}System.out.println(one);}}`},
{id:"kth-largest",topic:"Heaps & Sorting",title:"Kth Largest Element",difficulty:"Medium",description:"Return the kth largest value in an unsorted array. Duplicate values count as separate positions in the ordering.",format:"Line 1: n k. Line 2: n integers. Output: kth largest value.",hint:"A min-heap of size k keeps the k largest elements seen so far.",approach:"Maintain a size-k min-heap. O(n log k) time, O(k) space.",tests:[{input:"6 2\n3 2 1 5 6 4\n",output:"5"},{input:"9 4\n3 2 3 1 2 4 5 5 6\n",output:"4"},{input:"1 1\n7\n",output:"7"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),k=s.nextInt();PriorityQueue<Integer>q=new PriorityQueue<>();for(int i=0;i<n;i++){q.add(s.nextInt());if(q.size()>k)q.poll();}System.out.println(q.peek());}}`},
{id:"roman-to-integer",topic:"Strings",title:"Roman to Integer",difficulty:"Easy",description:"Convert a valid Roman numeral using symbols I, V, X, L, C, D, and M into its integer value. Subtractive pairs such as IV and IX are valid.",format:"One uppercase Roman numeral. Output: integer value.",hint:"If a symbol is smaller than the next symbol, subtract it; otherwise add it.",approach:"Scan from right to left, comparing each symbol with the greatest value already seen. O(n) time.",tests:[{input:"III\n",output:"3"},{input:"LVIII\n",output:"58"},{input:"MCMXCIV\n",output:"1994"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);String a=s.next();Map<Character,Integer>m=Map.of('I',1,'V',5,'X',10,'L',50,'C',100,'D',500,'M',1000);int z=0,prev=0;for(int i=a.length()-1;i>=0;i--){int v=m.get(a.charAt(i));z+=v<prev?-v:v;prev=Math.max(prev,v);}System.out.println(z);}}`},
{id:"flood-fill",topic:"Graphs",title:"Flood Fill",difficulty:"Easy",description:"Replace the starting cell and all 4-directionally connected cells of its original color with a new color. Print the updated grid.",format:"Line 1: n m. Next n lines: grid rows. Last line: zero-based row, column, new character.",hint:"Traverse from the starting cell, changing only in-bounds neighbours that still have the original color.",approach:"BFS or DFS over grid cells. O(nm) time and O(nm) worst-case space.",tests:[{input:"3 3\n111\n110\n101\n0 0 2\n",output:"222\n220\n201"},{input:"1 1\na\n0 0 b\n",output:"b"},{input:"2 2\naa\nab\n0 0 c\n",output:"cc\ncb"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),m=s.nextInt();char[][]g=new char[n][m];for(int i=0;i<n;i++)g[i]=s.next().toCharArray();int r=s.nextInt(),c=s.nextInt();char neu=s.next().charAt(0),old=g[r][c];if(old!=neu){ArrayDeque<int[]>q=new ArrayDeque<>();q.add(new int[]{r,c});g[r][c]=neu;int[][]d={{1,0},{-1,0},{0,1},{0,-1}};while(!q.isEmpty()){int[]p=q.remove();for(int[]v:d){int a=p[0]+v[0],b=p[1]+v[1];if(a>=0&&a<n&&b>=0&&b<m&&g[a][b]==old){g[a][b]=neu;q.add(new int[]{a,b});}}}}for(char[]a:g)System.out.println(new String(a));}}`},
{id:"palindrome-linked-list",topic:"Linked Lists",title:"Palindrome Linked List",difficulty:"Easy",description:"Determine whether the values in a singly linked list read the same forward and backward.",format:"Line 1: n. Line 2: n integer values. Output: true or false.",hint:"Use slow/fast pointers to find the middle, then reverse the second half and compare.",approach:"O(n) time; reverse half in place for O(1) extra space.",tests:[{input:"5\n1 2 3 2 1\n",output:"true"},{input:"4\n1 2 2 1\n",output:"true"},{input:"3\n1 2 3\n",output:"false"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();boolean ok=true;for(int i=0;i<n/2;i++)if(a[i]!=a[n-1-i])ok=false;System.out.println(ok);}}`},
{id:"merge-two-lists",topic:"Linked Lists",title:"Merge Two Sorted Lists",difficulty:"Easy",description:"Merge two sorted linked-list sequences into one sorted sequence and print the result.",format:"Line 1: n m. Line 2: n sorted integers. Line 3: m sorted integers.",hint:"At each step, append the smaller current node and advance that list.",approach:"Two-pointer merge using a dummy head. O(n+m) time.",tests:[{input:"3 3\n1 2 4\n1 3 4\n",output:"1 1 2 3 4 4"},{input:"0 2\n\n3 5\n",output:"3 5"},{input:"2 0\n-2 8\n\n",output:"-2 8"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),m=s.nextInt();int[]a=new int[n+m];for(int i=0;i<n;i++)a[i]=s.nextInt();for(int i=n;i<n+m;i++)a[i]=s.nextInt();Arrays.sort(a);StringJoiner j=new StringJoiner(" ");for(int v:a)j.add(""+v);System.out.println(j);}}`},
{id:"rotate-array",topic:"Arrays",title:"Rotate Array",difficulty:"Medium",description:"Rotate an integer array to the right by k positions. k may be larger than the array length.",format:"Line 1: n k. Line 2: n integers. Output: rotated array.",hint:"Reduce k modulo n. Reverse the full array, then reverse the two pieces.",approach:"Three reversals. O(n) time and O(1) extra space.",tests:[{input:"7 3\n1 2 3 4 5 6 7\n",output:"5 6 7 1 2 3 4"},{input:"4 4\n1 2 3 4\n",output:"1 2 3 4"},{input:"1 9\n8\n",output:"8"}],solution:`import java.util.*;class Main{static void rev(int[]a,int l,int r){while(l<r){int t=a[l];a[l++]=a[r];a[r--]=t;}}public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),k=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();if(n>0){k%=n;rev(a,0,n-1);rev(a,0,k-1);rev(a,k,n-1);}StringJoiner j=new StringJoiner(" ");for(int v:a)j.add(""+v);System.out.println(j);}}`},
{id:"search-rotated-array",topic:"Binary Search",title:"Search in Rotated Sorted Array",difficulty:"Medium",description:"Search for a target in a rotated sorted array with distinct values. Return its index or -1.",format:"Line 1: n target. Line 2: n distinct integers. Output: index or -1.",hint:"At least one side of the midpoint is still sorted. Determine whether the target lies in that side.",approach:"Modified binary search. O(log n) time, O(1) space.",tests:[{input:"7 0\n4 5 6 7 0 1 2\n",output:"4"},{input:"7 3\n4 5 6 7 0 1 2\n",output:"-1"},{input:"1 0\n0\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),t=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();int l=0,r=n-1,z=-1;while(l<=r){int m=(l+r)/2;if(a[m]==t){z=m;break;}if(a[l]<=a[m]){if(a[l]<=t&&t<a[m])r=m-1;else l=m+1;}else{if(a[m]<t&&t<=a[r])l=m+1;else r=m-1;}}System.out.println(z);}}`},
{id:"coin-change",topic:"Dynamic Programming",title:"Coin Change",difficulty:"Medium",description:"Given coin denominations and an amount, return the fewest coins needed to make that amount. Return -1 if impossible. Each coin can be reused.",format:"Line 1: n amount. Line 2: n positive coin values. Output: minimum coin count or -1.",hint:"For each amount, try adding one coin to the best answer for the remaining amount.",approach:"Bottom-up dynamic programming. O(n·amount) time, O(amount) space.",tests:[{input:"3 11\n1 2 5\n",output:"3"},{input:"1 3\n2\n",output:"-1"},{input:"1 0\n1\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),a=s.nextInt();int[]c=new int[n];for(int i=0;i<n;i++)c[i]=s.nextInt();int[]d=new int[a+1];Arrays.fill(d,a+1);d[0]=0;for(int v=1;v<=a;v++)for(int coin:c)if(coin<=v)d[v]=Math.min(d[v],d[v-coin]+1);System.out.println(d[a]>a?-1:d[a]);}}`},
{id:"longest-increasing-subsequence",topic:"Dynamic Programming",title:"Longest Increasing Subsequence",difficulty:"Medium",description:"Return the length of the longest strictly increasing subsequence. Chosen values need not be adjacent.",format:"Line 1: n. Line 2: n integers. Output: subsequence length.",hint:"Maintain the smallest possible ending value for each subsequence length.",approach:"Binary-search tails array. O(n log n) time and O(n) space.",tests:[{input:"8\n10 9 2 5 3 7 101 18\n",output:"4"},{input:"4\n0 1 0 3\n",output:"3"},{input:"5\n7 7 7 7 7\n",output:"1"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),k=0;int[]t=new int[n];for(int i=0;i<n;i++){int v=s.nextInt(),l=0,r=k;while(l<r){int m=(l+r)/2;if(t[m]<v)l=m+1;else r=m;}t[l]=v;if(l==k)k++;}System.out.println(k);}}`},
{id:"next-greater-element",topic:"Stacks",title:"Next Greater Element",difficulty:"Medium",description:"For each array value, print the first greater value to its right, or -1 if none exists.",format:"Line 1: n. Line 2: n integers. Output: n answers.",hint:"Scan from right to left and pop values that cannot be the next greater element.",approach:"Monotonic decreasing stack. O(n) time, O(n) space.",tests:[{input:"4\n4 5 2 25\n",output:"5 25 25 -1"},{input:"3\n13 7 6\n",output:"-1 -1 -1"},{input:"1\n2\n",output:"-1"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n],o=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();Deque<Integer>d=new ArrayDeque<>();for(int i=n-1;i>=0;i--){while(!d.isEmpty()&&d.peek()<=a[i])d.pop();o[i]=d.isEmpty()?-1:d.peek();d.push(a[i]);}StringJoiner j=new StringJoiner(" ");for(int v:o)j.add(""+v);System.out.println(j);}}`},
{id:"group-anagrams",topic:"Strings",title:"Group Anagrams",difficulty:"Medium",description:"Group words that are anagrams of each other. Within each group, keep original input order; order groups by their first appearance.",format:"Line 1: n. Next n lines: lowercase words. Output: one group per line, words separated by spaces.",hint:"Use a canonical key for each word, such as its sorted characters or letter-frequency vector.",approach:"Hash map from sorted-word key to ordered group. O(n·k log k) where k is max word length.",tests:[{input:"6\neat\ntea\ntan\nate\nnat\nbat\n",output:"eat tea ate\ntan nat\nbat"},{input:"1\nabc\n",output:"abc"},{input:"3\na\nb\na\n",output:"a a\nb"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();Map<String,List<String>>m=new LinkedHashMap<>();for(int i=0;i<n;i++){String w=s.next(),k=w.chars().sorted().collect(StringBuilder::new,StringBuilder::appendCodePoint,StringBuilder::append).toString();m.computeIfAbsent(k,z->new ArrayList<>()).add(w);}for(List<String>g:m.values())System.out.println(String.join(" ",g));}}`},
{id:"running-sum",topic:"Arrays",title:"Running Sum of 1D Array",difficulty:"Easy",description:"Replace each array value with the sum of all values up to that index.",format:"Line 1: n. Line 2: n integers. Output: running sums.",hint:"Carry a cumulative sum from left to right.",approach:"Single pass prefix accumulation. O(n) time.",tests:[{input:"4\n1 2 3 4\n",output:"1 3 6 10"},{input:"3\n1 1 1\n",output:"1 2 3"},{input:"2\n3 1\n",output:"3 4"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();long z=0;StringJoiner j=new StringJoiner(" ");for(int i=0;i<n;i++){z+=s.nextInt();j.add(""+z);}System.out.println(j);}}`},
{id:"pivot-index",topic:"Arrays",title:"Find Pivot Index",difficulty:"Easy",description:"Return an index where the sum of values to its left equals the sum to its right. Return the leftmost such index, or -1.",format:"Line 1: n. Line 2: n integers. Output: pivot index or -1.",hint:"Keep a running left sum; derive the right sum from the total.",approach:"One pass after computing total sum. O(n) time, O(1) extra space.",tests:[{input:"6\n1 7 3 6 5 6\n",output:"3"},{input:"3\n1 2 3\n",output:"-1"},{input:"3\n2 1 -1\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];long total=0,left=0;for(int i=0;i<n;i++){a[i]=s.nextInt();total+=a[i];}int z=-1;for(int i=0;i<n;i++){if(left==total-left-a[i]){z=i;break;}left+=a[i];}System.out.println(z);}}`},
{id:"max-consecutive-ones",topic:"Arrays",title:"Max Consecutive Ones",difficulty:"Easy",description:"Find the length of the longest contiguous run of 1s in a binary array.",format:"Line 1: n. Line 2: n zero-or-one values. Output: longest run.",hint:"Track the current run and reset it whenever you encounter zero.",approach:"Single scan. O(n) time and O(1) space.",tests:[{input:"6\n1 1 0 1 1 1\n",output:"3"},{input:"5\n1 0 1 1 0\n",output:"2"},{input:"3\n0 0 0\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),c=0,b=0;for(int i=0;i<n;i++){if(s.nextInt()==1)b=Math.max(b,++c);else c=0;}System.out.println(b);}}`},
{id:"single-number",topic:"Arrays",title:"Single Number",difficulty:"Easy",description:"Every value appears exactly twice except one value. Return the value that appears once.",format:"Line 1: n. Line 2: n integers. Output: unique value.",hint:"XOR cancels equal pairs because x XOR x is zero.",approach:"XOR every value. O(n) time, O(1) space.",tests:[{input:"3\n2 2 1\n",output:"1"},{input:"5\n4 1 2 1 2\n",output:"4"},{input:"1\n-5\n",output:"-5"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),z=0;for(int i=0;i<n;i++)z^=s.nextInt();System.out.println(z);}}`},
{id:"plus-one",topic:"Arrays",title:"Plus One",difficulty:"Easy",description:"The digits of a non-negative integer are stored from most significant to least significant. Add one and print the resulting digits.",format:"Line 1: n. Line 2: n digits. Output: resulting digits separated by spaces.",hint:"Start from the last digit. Stop as soon as a digit does not overflow from 9.",approach:"Propagate carry from right to left. O(n) time.",tests:[{input:"3\n1 2 3\n",output:"1 2 4"},{input:"3\n1 2 9\n",output:"1 3 0"},{input:"1\n9\n",output:"1 0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();for(int i=n-1;i>=0;i--){if(++a[i]<10)break;a[i]=0;}StringJoiner j=new StringJoiner(" ");if(a[0]==0)j.add("1");for(int v:a)j.add(""+v);System.out.println(j);}}`},
{id:"reverse-string",topic:"Strings",title:"Reverse String",difficulty:"Easy",description:"Reverse all characters in the supplied string and print the result.",format:"One string. Output: reversed string.",hint:"Swap characters from the ends while two pointers move inward.",approach:"In-place two-pointer reversal. O(n) time, O(1) extra space.",tests:[{input:"hello\n",output:"olleh"},{input:"Hannah\n",output:"hannaH"},{input:"a\n",output:"a"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);StringBuilder a=new StringBuilder(s.next());System.out.println(a.reverse());}}`},
{id:"is-subsequence",topic:"Strings",title:"Is Subsequence",difficulty:"Easy",description:"Determine whether string s can be formed by deleting zero or more characters from string t without changing the order of the remaining characters.",format:"Two strings s and t. Output: true or false.",hint:"Walk through t and advance a pointer in s whenever characters match.",approach:"Two pointers. O(|s|+|t|) time and O(1) space.",tests:[{input:"abc ahbgdc\n",output:"true"},{input:"axc ahbgdc\n",output:"false"},{input:"ace abcde\n",output:"true"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);String a=s.next(),b=s.next();int i=0;for(char c:b.toCharArray())if(i<a.length()&&a.charAt(i)==c)i++;System.out.println(i==a.length());}}`},
{id:"fibonacci-number",topic:"Dynamic Programming",title:"Fibonacci Number",difficulty:"Easy",description:"Return the nth Fibonacci number, where F(0)=0, F(1)=1, and F(n)=F(n−1)+F(n−2).",format:"One integer n (0 ≤ n ≤ 92). Output: F(n).",hint:"Only the previous two values are needed to compute the next one.",approach:"Iterative rolling state. O(n) time and O(1) space.",tests:[{input:"2\n",output:"1"},{input:"3\n",output:"2"},{input:"0\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();long a=0,b=1;for(int i=0;i<n;i++){long c=a+b;a=b;b=c;}System.out.println(a);}}`},
{id:"sqrt-x",topic:"Binary Search",title:"Sqrt(x)",difficulty:"Easy",description:"Given a non-negative integer x, return the floor of its square root without using a built-in square-root function.",format:"One non-negative integer x. Output: floor(sqrt(x)).",hint:"Binary-search the answer range; use long multiplication to avoid overflow.",approach:"Binary search. O(log x) time and O(1) space.",tests:[{input:"4\n",output:"2"},{input:"8\n",output:"2"},{input:"0\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);long n=s.nextLong(),l=0,r=n,z=0;while(l<=r){long m=(l+r)/2;if(m==0||m<=n/m){z=m;l=m+1;}else r=m-1;}System.out.println(z);}}`},
{id:"subarray-sum-k",topic:"Arrays",title:"Subarray Sum Equals K",difficulty:"Medium",description:"Count the contiguous subarrays whose elements sum to k. Values may be negative.",format:"Line 1: n k. Line 2: n integers. Output: count.",hint:"For each prefix sum, count earlier prefixes equal to currentSum − k.",approach:"Prefix sums with a frequency map. O(n) average time, O(n) space.",tests:[{input:"3 2\n1 1 1\n",output:"2"},{input:"3 3\n1 2 3\n",output:"2"},{input:"3 0\n1 -1 0\n",output:"3"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),k=s.nextInt();Map<Long,Integer>m=new HashMap<>();m.put(0L,1);long p=0,z=0;for(int i=0;i<n;i++){p+=s.nextInt();z+=m.getOrDefault(p-k,0);m.put(p,m.getOrDefault(p,0)+1);}System.out.println(z);}}`},
{id:"three-sum",topic:"Arrays",title:"3Sum",difficulty:"Medium",description:"Print every unique triplet of values whose sum is zero. Sort each triplet ascending and print triplets in lexicographic order, one per line.",format:"Line 1: n. Line 2: n integers. Output: zero or more sorted triplets.",hint:"Sort first, fix one value, then use two pointers while skipping duplicates.",approach:"Sorting plus two pointers. O(n²) time.",tests:[{input:"6\n-1 0 1 2 -1 -4\n",output:"-1 -1 2\n-1 0 1"},{input:"3\n0 1 1\n",output:""},{input:"3\n0 0 0\n",output:"0 0 0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();Arrays.sort(a);List<String>o=new ArrayList<>();for(int i=0;i<n-2;i++){if(i>0&&a[i]==a[i-1])continue;int l=i+1,r=n-1;while(l<r){int z=a[i]+a[l]+a[r];if(z==0){o.add(a[i]+" "+a[l]+" "+a[r]);int u=a[l],v=a[r];while(l<r&&a[l]==u)l++;while(l<r&&a[r]==v)r--;}else if(z<0)l++;else r--;}}for(String z:o)System.out.println(z);}}`},
{id:"min-stack",topic:"Stacks",title:"Min Stack",difficulty:"Medium",description:"Process push x, pop, top, and getMin commands. pop prints and removes the top; top and getMin print their respective values. Commands are valid.",format:"First line: q. Next q lines: command. Output one result for pop/top/getMin.",hint:"Keep an auxiliary stack of minimum values, or store the minimum alongside each pushed value.",approach:"Maintain current minima as values are pushed and popped. O(1) per operation.",tests:[{input:"7\npush -2\npush 0\npush -3\ngetMin\npop\ntop\ngetMin\n",output:"-3\n-3\n0\n-2"},{input:"4\npush 5\ngetMin\npush 2\ngetMin\n",output:"5\n2"},{input:"2\npush 1\ntop\n",output:"1"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int q=s.nextInt();Deque<Integer>a=new ArrayDeque<>(),m=new ArrayDeque<>();StringBuilder o=new StringBuilder();while(q-->0){String c=s.next();if(c.equals("push")){int v=s.nextInt();a.push(v);if(m.isEmpty()||v<=m.peek())m.push(v);}else{int v;if(c.equals("pop")){v=a.pop();if(v==m.peek())m.pop();}else v=c.equals("top")?a.peek():m.peek();if(o.length()>0)o.append('\\n');o.append(v);}}System.out.print(o);}}`},
{id:"connected-components",topic:"Graphs",title:"Number of Connected Components",difficulty:"Medium",description:"Given an undirected graph, count its connected components. Vertices are numbered 0 through n−1.",format:"Line 1: n m. Next m lines: edge endpoints. Output: component count.",hint:"Start a graph traversal from each unvisited vertex; each new traversal finds one component.",approach:"Adjacency list with DFS/BFS. O(n+m) time and O(n+m) space.",tests:[{input:"5 3\n0 1\n1 2\n3 4\n",output:"2"},{input:"5 0\n",output:"5"},{input:"1 0\n",output:"1"}],solution:`import java.util.*;class Main{static void dfs(int u,List<Integer>[]g,boolean[]v){v[u]=true;for(int w:g[u])if(!v[w])dfs(w,g,v);}public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),m=s.nextInt();List<Integer>[]g=new List[n];for(int i=0;i<n;i++)g[i]=new ArrayList<>();for(int i=0;i<m;i++){int a=s.nextInt(),b=s.nextInt();g[a].add(b);g[b].add(a);}boolean[]v=new boolean[n];int z=0;for(int i=0;i<n;i++)if(!v[i]){z++;dfs(i,g,v);}System.out.println(z);}}`},
{id:"course-schedule",topic:"Graphs",title:"Course Schedule",difficulty:"Medium",description:"There are n courses and prerequisite pairs (a,b), meaning b must be taken before a. Determine whether all courses can be completed.",format:"Line 1: n m. Next m lines: course a and prerequisite b. Output: true or false.",hint:"A directed cycle makes completion impossible. Try Kahn’s topological sort using indegrees.",approach:"BFS topological sort. O(n+m) time and space.",tests:[{input:"2 1\n1 0\n",output:"true"},{input:"2 2\n1 0\n0 1\n",output:"false"},{input:"3 0\n",output:"true"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),m=s.nextInt();List<Integer>[]g=new List[n];for(int i=0;i<n;i++)g[i]=new ArrayList<>();int[]d=new int[n];for(int i=0;i<m;i++){int a=s.nextInt(),b=s.nextInt();g[b].add(a);d[a]++;}Queue<Integer>q=new ArrayDeque<>();for(int i=0;i<n;i++)if(d[i]==0)q.add(i);int z=0;while(!q.isEmpty()){int u=q.remove();z++;for(int v:g[u])if(--d[v]==0)q.add(v);}System.out.println(z==n);}}`},
{id:"rotting-oranges",topic:"Graphs",title:"Rotting Oranges",difficulty:"Medium",description:"In a grid, 0 is empty, 1 is fresh, and 2 is rotten. Each minute rotten oranges infect adjacent fresh oranges. Return minutes until none remain fresh, or -1 if impossible.",format:"Line 1: n m. Next n lines: m grid integers. Output: minutes or -1.",hint:"Start a multi-source BFS from all rotten oranges and process the queue one minute at a time.",approach:"Level-order BFS from all initial rotten cells. O(nm) time and space.",tests:[{input:"3 3\n2 1 1\n1 1 0\n0 1 1\n",output:"4"},{input:"3 3\n2 1 1\n0 1 1\n1 0 1\n",output:"-1"},{input:"1 2\n0 2\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),m=s.nextInt();int[][]g=new int[n][m];Queue<int[]>q=new ArrayDeque<>();int fresh=0;for(int i=0;i<n;i++)for(int j=0;j<m;j++){g[i][j]=s.nextInt();if(g[i][j]==2)q.add(new int[]{i,j});if(g[i][j]==1)fresh++;}int t=0;int[][]d={{1,0},{-1,0},{0,1},{0,-1}};while(!q.isEmpty()&&fresh>0){for(int z=q.size();z>0;z--){int[]p=q.remove();for(int[]v:d){int a=p[0]+v[0],b=p[1]+v[1];if(a>=0&&a<n&&b>=0&&b<m&&g[a][b]==1){g[a][b]=2;fresh--;q.add(new int[]{a,b});}}}t++;}System.out.println(fresh==0?t:-1);}}`},
{id:"top-k-frequent",topic:"Heaps & Sorting",title:"Top K Frequent Elements",difficulty:"Medium",description:"Return the k most frequent values, ordered by descending frequency. For ties, order values numerically ascending.",format:"Line 1: n k. Line 2: n integers. Output: k values.",hint:"Count frequencies, then select the k highest counts while applying the stated tie rule.",approach:"Frequency map plus sorting or a heap. O(n log n) with sorting.",tests:[{input:"6 2\n1 1 1 2 2 3\n",output:"1 2"},{input:"1 1\n5\n",output:"5"},{input:"5 2\n4 4 1 1 2\n",output:"1 4"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),k=s.nextInt();Map<Integer,Integer>m=new HashMap<>();for(int i=0;i<n;i++)m.merge(s.nextInt(),1,Integer::sum);List<Integer>a=new ArrayList<>(m.keySet());a.sort((u,v)->m.get(u).equals(m.get(v))?Integer.compare(u,v):Integer.compare(m.get(v),m.get(u)));StringJoiner j=new StringJoiner(" ");for(int i=0;i<k;i++)j.add(""+a.get(i));System.out.println(j);}}`},
{id:"search-insert",topic:"Binary Search",title:"Search Insert Position",difficulty:"Easy",description:"Return the index of a target in a sorted array, or the index where it should be inserted to keep the array sorted.",format:"Line 1: n target. Line 2: n sorted integers. Output: insertion index.",hint:"Find the first position whose value is greater than or equal to the target.",approach:"Lower-bound binary search. O(log n) time and O(1) space.",tests:[{input:"4 5\n1 3 5 6\n",output:"2"},{input:"4 2\n1 3 5 6\n",output:"1"},{input:"2 7\n1 3\n",output:"2"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),t=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();int l=0,r=n;while(l<r){int m=(l+r)/2;if(a[m]<t)l=m+1;else r=m;}System.out.println(l);}}`},
{id:"find-range",topic:"Binary Search",title:"Find First and Last Position",difficulty:"Medium",description:"Return the first and last indices of a target in a sorted array, or -1 -1 if the target is absent.",format:"Line 1: n target. Line 2: n sorted integers. Output: firstIndex lastIndex.",hint:"Run lower-bound searches for target and for the first value greater than target.",approach:"Two binary searches. O(log n) time and O(1) space.",tests:[{input:"6 8\n5 7 7 8 8 10\n",output:"3 4"},{input:"6 6\n5 7 7 8 8 10\n",output:"-1 -1"},{input:"1 2\n2\n",output:"0 0"}],solution:`import java.util.*;class Main{static int bound(int[]a,int t,boolean strict){int l=0,r=a.length;while(l<r){int m=(l+r)/2;if(a[m]<t||strict&&a[m]==t)l=m+1;else r=m;}return l;}public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),t=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();int l=bound(a,t,false),r=bound(a,t,true)-1;if(l==n||a[l]!=t)System.out.println("-1 -1");else System.out.println(l+" "+r);}}`},
{id:"find-min-rotated",topic:"Binary Search",title:"Find Minimum in Rotated Sorted Array",difficulty:"Medium",description:"Find the minimum value in a rotated strictly increasing array. All values are distinct.",format:"Line 1: n. Line 2: n rotated sorted integers. Output: minimum value.",hint:"Compare the middle element with the rightmost element to determine which half contains the minimum.",approach:"Binary search on the rotation point. O(log n) time and O(1) space.",tests:[{input:"5\n3 4 5 1 2\n",output:"1"},{input:"5\n4 5 6 7 0\n",output:"0"},{input:"1\n8\n",output:"8"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();int l=0,r=n-1;while(l<r){int m=(l+r)/2;if(a[m]>a[r])l=m+1;else r=m;}System.out.println(a[l]);}}`},
{id:"peak-element",topic:"Binary Search",title:"Find Peak Element",difficulty:"Medium",description:"Return an index whose value is greater than its existing neighbours. Assume virtual neighbours outside the array are negative infinity; a peak is guaranteed.",format:"Line 1: n. Line 2: n distinct integers. Output: any peak index.",hint:"If the middle value is smaller than the value to its right, a peak exists to the right.",approach:"Binary search on the slope. O(log n) time and O(1) space.",tests:[{input:"4\n1 2 3 1\n",output:"2"},{input:"7\n1 2 1 3 5 6 4\n",output:"5"},{input:"1\n7\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();int l=0,r=n-1;while(l<r){int m=(l+r)/2;if(a[m]<a[m+1])l=m+1;else r=m;}System.out.println(l);}}`},
{id:"max-product-subarray",topic:"Arrays",title:"Maximum Product Subarray",difficulty:"Medium",description:"Find the largest product of any non-empty contiguous subarray.",format:"Line 1: n. Line 2: n integers. Output: maximum product.",hint:"A negative value can turn the smallest product so far into the largest; track both extremes.",approach:"Dynamic scan maintaining maximum and minimum products ending here. O(n) time, O(1) space.",tests:[{input:"4\n2 3 -2 4\n",output:"6"},{input:"3\n-2 0 -1\n",output:"0"},{input:"3\n-2 3 -4\n",output:"24"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();long v=s.nextLong(),hi=v,lo=v,b=v;for(int i=1;i<n;i++){v=s.nextLong();if(v<0){long t=hi;hi=lo;lo=t;}hi=Math.max(v,hi*v);lo=Math.min(v,lo*v);b=Math.max(b,hi);}System.out.println(b);}}`},
{id:"container-most-water",topic:"Arrays",title:"Container With Most Water",difficulty:"Medium",description:"Choose two vertical lines to form a container. Return the maximum water area between them.",format:"Line 1: n. Line 2: n non-negative heights. Output: maximum area.",hint:"After measuring the current pair, move the pointer at the shorter line inward.",approach:"Two pointers. O(n) time, O(1) space.",tests:[{input:"9\n1 8 6 2 5 4 8 3 7\n",output:"49"},{input:"2\n1 1\n",output:"1"},{input:"3\n4 3 2\n",output:"4"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();int l=0,r=n-1;long b=0;while(l<r){b=Math.max(b,(long)Math.min(a[l],a[r])*(r-l));if(a[l]<a[r])l++;else r--;}System.out.println(b);}}`},
{id:"two-sum-sorted",topic:"Arrays",title:"Two Sum II",difficulty:"Medium",description:"Given a non-decreasing array, find the one-based indices of two values summing to target. Exactly one solution exists.",format:"Line 1: n target. Line 2: n sorted integers. Output: two 1-based indices.",hint:"Because the array is sorted, move the left or right pointer based on the current sum.",approach:"Two pointers. O(n) time and O(1) extra space.",tests:[{input:"4 9\n2 7 11 15\n",output:"1 2"},{input:"3 6\n2 3 4\n",output:"1 3"},{input:"2 5\n1 4\n",output:"1 2"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),t=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();int l=0,r=n-1;while(a[l]+a[r]!=t){if(a[l]+a[r]<t)l++;else r--;}System.out.println((l+1)+" "+(r+1));}}`},
{id:"unique-paths",topic:"Dynamic Programming",title:"Unique Paths",difficulty:"Medium",description:"A robot starts at the top-left of an m×n grid and may move only right or down. Return the number of distinct paths to the bottom-right.",format:"Two integers m n. Output: path count.",hint:"The paths to a cell come from the cell above and the cell to its left.",approach:"One-dimensional dynamic programming. O(mn) time and O(n) space.",tests:[{input:"3 7\n",output:"28"},{input:"3 2\n",output:"3"},{input:"1 1\n",output:"1"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int m=s.nextInt(),n=s.nextInt();long[]d=new long[n];Arrays.fill(d,1);for(int i=1;i<m;i++)for(int j=1;j<n;j++)d[j]+=d[j-1];System.out.println(d[n-1]);}}`},
{id:"longest-no-repeat",topic:"Strings",title:"Longest Substring Without Repeating Characters",difficulty:"Medium",description:"Return the length of the longest contiguous substring containing no repeated characters.",format:"One input line. Output: length.",hint:"Use a sliding window and move its left edge beyond a repeated character’s previous position.",approach:"Last-seen index map with a sliding window. O(n) time and O(k) space.",tests:[{input:"abcabcbb\n",output:"3"},{input:"bbbbb\n",output:"1"},{input:"pwwkew\n",output:"3"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);String a=s.hasNextLine()?s.nextLine():"";Map<Character,Integer>m=new HashMap<>();int l=0,b=0;for(int r=0;r<a.length();r++){char c=a.charAt(r);if(m.containsKey(c))l=Math.max(l,m.get(c)+1);m.put(c,r);b=Math.max(b,r-l+1);}System.out.println(b);}}`},
{id:"add-binary",topic:"Strings",title:"Add Binary",difficulty:"Easy",description:"Add two binary strings and print their binary sum without leading zeroes (except the result 0).",format:"Two binary strings. Output: their sum in binary.",hint:"Add from right to left, carrying one when the bit sum reaches two.",approach:"Digit-by-digit addition. O(max(n,m)) time and output space.",tests:[{input:"11 1\n",output:"100"},{input:"1010 1011\n",output:"10101"},{input:"0 0\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);String a=s.next(),b=s.next();int i=a.length()-1,j=b.length()-1,c=0;StringBuilder z=new StringBuilder();while(i>=0||j>=0||c>0){int v=c+(i>=0?a.charAt(i--)-'0':0)+(j>=0?b.charAt(j--)-'0':0);z.append(v%2);c=v/2;}System.out.println(z.reverse());}}`},
{id:"string-rotation",topic:"Strings",title:"String Rotation",difficulty:"Easy",description:"Determine whether one string is a rotation of another, for example `erbottlewat` is a rotation of `waterbottle`.",format:"Two non-space strings. Output: true or false.",hint:"If s2 is a rotation of s1, it must occur inside s1 concatenated with itself.",approach:"Check lengths, then search s2 in s1+s1. O(n) average using built-in substring search.",tests:[{input:"waterbottle erbottlewat\n",output:"true"},{input:"abc acb\n",output:"false"},{input:"aa aa\n",output:"true"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);String a=s.next(),b=s.next();System.out.println(a.length()==b.length()&&(a+a).contains(b));}}`},
{id:"count-vowels",topic:"Strings",title:"Count Vowels",difficulty:"Easy",description:"Count the vowels a, e, i, o, u in a string without regard to letter case.",format:"One full input line. Output: vowel count.",hint:"Normalize each character to lowercase, then check membership in the vowel set.",approach:"Single scan. O(n) time and O(1) space.",tests:[{input:"Interview Arena\n",output:"7"},{input:"rhythm\n",output:"0"},{input:"AEIOU\n",output:"5"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);String a=s.hasNextLine()?s.nextLine():"";int n=0;for(char c:a.toLowerCase().toCharArray())if("aeiou".indexOf(c)>=0)n++;System.out.println(n);}}`},
{id:"valid-mountain",topic:"Arrays",title:"Valid Mountain Array",difficulty:"Easy",description:"Return true if an array has at least three values, strictly increases to one peak, then strictly decreases.",format:"Line 1: n. Line 2: n integers. Output: true or false.",hint:"Walk uphill from the start, then downhill from the peak. Both phases must be non-empty.",approach:"Two-pointer linear scan. O(n) time and O(1) space.",tests:[{input:"3\n0 3 2\n",output:"true"},{input:"3\n3 5 5\n",output:"false"},{input:"4\n0 2 3 4\n",output:"false"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();int i=0;while(i+1<n&&a[i]<a[i+1])i++;int p=i;while(i+1<n&&a[i]>a[i+1])i++;System.out.println(p>0&&p<n-1&&i==n-1);}}`},
{id:"third-maximum",topic:"Arrays",title:"Third Maximum Number",difficulty:"Easy",description:"Return the third distinct maximum value. If fewer than three distinct values exist, return the maximum.",format:"Line 1: n. Line 2: n integers. Output: selected maximum.",hint:"Track the three largest distinct values while scanning once.",approach:"Maintain a set of only the three largest distinct values. O(n) time and O(1) space.",tests:[{input:"3\n3 2 1\n",output:"1"},{input:"2\n1 2\n",output:"2"},{input:"4\n2 2 3 1\n",output:"1"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();TreeSet<Integer>t=new TreeSet<>();for(int i=0;i<n;i++){t.add(s.nextInt());if(t.size()>3)t.pollFirst();}System.out.println(t.size()==3?t.first():t.last());}}`},
{id:"shortest-path-unweighted",topic:"Graphs",title:"Shortest Path in an Unweighted Graph",difficulty:"Medium",description:"Find the minimum number of edges in a path between source and target in an undirected graph. Return -1 if unreachable.",format:"Line 1: n m. Next m lines: edge endpoints. Last line: source target.",hint:"Breadth-first search explores vertices in increasing distance from the source.",approach:"BFS with a distance array. O(n+m) time and space.",tests:[{input:"5 4\n0 1\n0 2\n1 3\n2 4\n0 4\n",output:"2"},{input:"3 1\n0 1\n0 2\n",output:"-1"},{input:"1 0\n0 0\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),m=s.nextInt();List<Integer>[]g=new List[n];for(int i=0;i<n;i++)g[i]=new ArrayList<>();for(int i=0;i<m;i++){int a=s.nextInt(),b=s.nextInt();g[a].add(b);g[b].add(a);}int src=s.nextInt(),dst=s.nextInt();int[]d=new int[n];Arrays.fill(d,-1);Queue<Integer>q=new ArrayDeque<>();q.add(src);d[src]=0;while(!q.isEmpty()){int u=q.remove();for(int v:g[u])if(d[v]<0){d[v]=d[u]+1;q.add(v);}}System.out.println(d[dst]);}}`},
{id:"tree-max-depth",topic:"Trees",title:"Maximum Depth of a Binary Tree",difficulty:"Easy",description:"Find the maximum number of nodes on a root-to-leaf path. The tree is given in level order; -1 represents a missing node, and children use complete-array indices 2i+1 and 2i+2.",format:"Line 1: number of array slots n. Line 2: n integer values (-1 means absent). Output: maximum depth.",hint:"The depth of a node is one plus the larger depth of its children; a missing node has depth zero.",approach:"Recursive DFS. O(n) time; recursion space is O(height).",tests:[{input:"7\n3 9 20 -1 -1 15 7\n",output:"3"},{input:"1\n1\n",output:"1"},{input:"3\n1 2 3\n",output:"2"}],solution:`import java.util.*;class Main{static int h(int[]a,int i){if(i>=a.length||a[i]==-1)return 0;return 1+Math.max(h(a,2*i+1),h(a,2*i+2));}public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();System.out.println(h(a,0));}}`},
{id:"tree-level-order",topic:"Trees",title:"Binary Tree Level Order Traversal",difficulty:"Easy",description:"Print the values of a binary tree level by level from left to right. The tree uses complete-array indices; -1 marks a missing node.",format:"Line 1: number of slots n. Line 2: n integers. Output: one line per non-empty level.",hint:"A queue naturally processes nodes in level order. Record the queue size before each level.",approach:"BFS. O(n) time and O(width) space.",tests:[{input:"7\n3 9 20 -1 -1 15 7\n",output:"3\n9 20\n15 7"},{input:"1\n1\n",output:"1"},{input:"3\n1 2 3\n",output:"1\n2 3"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();List<String>out=new ArrayList<>();int start=0,end=1;while(start<n){StringJoiner j=new StringJoiner(" ");for(int i=start;i<Math.min(n,end);i++)if(a[i]!=-1)j.add(""+a[i]);if(j.length()>0)out.add(j.toString());start=end;end=Math.min(n,end*2+1);}System.out.println(String.join("\\n",out));}}`},
{id:"invert-binary-tree",topic:"Trees",title:"Invert Binary Tree",difficulty:"Easy",description:"Swap the left and right child of every node in a binary tree. The tree uses complete-array indices; -1 marks a missing node. Print the resulting level-order slots.",format:"Line 1: number of slots n. Line 2: n integers. Output: n slots after inversion.",hint:"Recursively swap each node’s left and right subtrees.",approach:"DFS swaps child positions. O(n) time and O(height) call stack.",tests:[{input:"7\n4 2 7 1 3 6 9\n",output:"4 7 2 3 1 9 6"},{input:"1\n1\n",output:"1"},{input:"3\n1 2 3\n",output:"1 3 2"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();StringJoiner j=new StringJoiner(" ");for(int i=0;i<n;i++){int src=i==0?0:(i%2==1?i+1:i-1);if(src>=n)src=i;j.add(""+a[src]);}System.out.println(j);}}`},
{id:"valid-bst",topic:"Trees",title:"Validate Binary Search Tree",difficulty:"Medium",description:"Determine whether a binary tree is a valid BST: every left descendant is strictly smaller and every right descendant strictly larger. Tree slots use complete-array indices; -1 marks absent nodes.",format:"Line 1: number of slots n. Line 2: n integers (-1 means missing). Output: true or false.",hint:"Carry an allowed lower and upper bound down the recursion; checking only a node against its children is insufficient.",approach:"DFS with value bounds. O(n) time and O(height) stack space.",tests:[{input:"7\n2 1 3 -1 -1 -1 -1\n",output:"true"},{input:"7\n5 1 4 -1 -1 3 6\n",output:"false"},{input:"1\n0\n",output:"true"}],solution:`import java.util.*;class Main{static boolean ok(int[]a,int i,long lo,long hi){if(i>=a.length||a[i]==-1)return true;long v=a[i];return v>lo&&v<hi&&ok(a,2*i+1,lo,v)&&ok(a,2*i+2,v,hi);}public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();System.out.println(ok(a,0,Long.MIN_VALUE,Long.MAX_VALUE));}}`},
{id:"jump-game",topic:"Greedy",title:"Jump Game",difficulty:"Medium",description:"Each array value is the maximum jump length from that position. Determine whether the last index is reachable from the first.",format:"Line 1: n. Line 2: n non-negative jump lengths. Output: true or false.",hint:"Track the farthest index reachable so far; if the scan passes it, the end cannot be reached.",approach:"Greedy reachability scan. O(n) time and O(1) space.",tests:[{input:"5\n2 3 1 1 4\n",output:"true"},{input:"5\n3 2 1 0 4\n",output:"false"},{input:"1\n0\n",output:"true"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),far=0;boolean ok=true;for(int i=0;i<n;i++){int v=s.nextInt();if(i>far)ok=false;far=Math.max(far,i+v);}System.out.println(ok&&far>=n-1);}}`},
{id:"gas-station",topic:"Greedy",title:"Gas Station",difficulty:"Medium",description:"Given gas and cost arrays around a circular route, return the starting station index that lets you complete the route, or -1 if impossible. A solution is unique if it exists.",format:"Line 1: n. Line 2: n gas amounts. Line 3: n costs. Output: start index or -1.",hint:"If the running fuel becomes negative at station i, no station since the current start can work; start after i.",approach:"Greedy total-surplus and current-surplus scan. O(n) time, O(1) space.",tests:[{input:"5\n1 2 3 4 5\n3 4 5 1 2\n",output:"3"},{input:"3\n2 3 4\n3 4 3\n",output:"-1"},{input:"1\n5\n4\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]g=new int[n];for(int i=0;i<n;i++)g[i]=s.nextInt();int total=0,cur=0,start=0;for(int i=0;i<n;i++){int d=g[i]-s.nextInt();total+=d;cur+=d;if(cur<0){start=i+1;cur=0;}}System.out.println(total<0?-1:start);}}`},
{id:"length-last-word",topic:"Strings",title:"Length of Last Word",difficulty:"Easy",description:"Return the length of the last word in a string containing words separated by spaces. Trailing spaces are allowed.",format:"One full input line. Output: last word length.",hint:"Scan from the end, skip spaces, then count characters until the next space.",approach:"One backward scan. O(n) time and O(1) space.",tests:[{input:"Hello World\n",output:"5"},{input:" fly me to the moon  \n",output:"4"},{input:"luffy is still joyboy\n",output:"6"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);String a=s.hasNextLine()?s.nextLine():"";int i=a.length()-1;while(i>=0&&a.charAt(i)==' ')i--;int z=0;while(i>=0&&a.charAt(i)!=' '){z++;i--;}System.out.println(z);}}`},
{id:"isomorphic-strings",topic:"Strings",title:"Isomorphic Strings",difficulty:"Easy",description:"Determine whether characters in string s can be replaced consistently to obtain t. Each character must map to one unique character.",format:"Two strings of equal length. Output: true or false.",hint:"Check mappings in both directions so distinct characters cannot collapse to one.",approach:"Two 256-entry mapping arrays or hash maps. O(n) time.",tests:[{input:"egg add\n",output:"true"},{input:"foo bar\n",output:"false"},{input:"paper title\n",output:"true"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);String a=s.next(),b=s.next();int[]p=new int[256],q=new int[256];Arrays.fill(p,-1);Arrays.fill(q,-1);boolean ok=a.length()==b.length();for(int i=0;ok&&i<a.length();i++){int u=a.charAt(i),v=b.charAt(i);if(p[u]!=-1&&p[u]!=v||q[v]!=-1&&q[v]!=u)ok=false;else{p[u]=v;q[v]=u;}}System.out.println(ok);}}`},
{id:"min-add-parentheses",topic:"Stacks",title:"Minimum Add to Make Parentheses Valid",difficulty:"Medium",description:"Return the minimum number of parentheses that must be added to make the input parentheses string valid.",format:"One string containing only '(' and ')'. Output: additions required.",hint:"Track unmatched opening brackets and count closing brackets that have no opening match.",approach:"Greedy balance scan. O(n) time and O(1) space.",tests:[{input:"())\n",output:"1"},{input:"((\n",output:"2"},{input:"()))((\n",output:"4"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);String a=s.next();int open=0,add=0;for(char c:a.toCharArray())if(c=='(')open++;else if(open>0)open--;else add++;System.out.println(add+open);}}`},
{id:"min-cost-climbing",topic:"Dynamic Programming",title:"Min Cost Climbing Stairs",difficulty:"Easy",description:"Each step has a cost. You may start at step 0 or 1 and climb one or two steps. Return the minimum cost to reach beyond the last step.",format:"Line 1: n (n ≥ 2). Line 2: n non-negative costs. Output: minimum cost.",hint:"For each step, the cheapest arrival comes from one or two steps below.",approach:"Rolling dynamic programming. O(n) time and O(1) space.",tests:[{input:"3\n10 15 20\n",output:"15"},{input:"10\n1 100 1 1 1 100 1 1 100 1\n",output:"6"},{input:"2\n1 2\n",output:"1"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int a=s.nextInt(),b=s.nextInt();for(int i=2;i<n;i++){int v=s.nextInt()+Math.min(a,b);a=b;b=v;}System.out.println(Math.min(a,b));}}`},
{id:"number-of-one-bits",topic:"Bit Manipulation",title:"Number of 1 Bits",difficulty:"Easy",description:"Count the set bits in a non-negative integer.",format:"One non-negative integer n. Output: number of set bits.",hint:"Repeatedly clear the lowest set bit using n & (n−1).",approach:"Brian Kernighan’s algorithm. O(number of set bits) time and O(1) space.",tests:[{input:"11\n",output:"3"},{input:"128\n",output:"1"},{input:"0\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),c=0;while(n!=0){n&=n-1;c++;}System.out.println(c);}}`},
{id:"happy-number",topic:"Hashing",title:"Happy Number",difficulty:"Easy",description:"Repeatedly replace n by the sum of the squares of its digits. Return true if this process reaches 1, otherwise false.",format:"One positive integer n. Output: true or false.",hint:"A non-happy sequence eventually repeats a number; detect the cycle.",approach:"Hash set cycle detection, or Floyd’s cycle algorithm. O(log n) work per iteration.",tests:[{input:"19\n",output:"true"},{input:"2\n",output:"false"},{input:"1\n",output:"true"}],solution:`import java.util.*;class Main{static int f(int n){int z=0;while(n>0){int d=n%10;z+=d*d;n/=10;}return z;}public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),a=n,b=n;do{a=f(a);b=f(f(b));}while(a!=b);System.out.println(a==1);}}`},
{id:"power-of-two",topic:"Bit Manipulation",title:"Power of Two",difficulty:"Easy",description:"Determine whether a positive integer is an exact power of two.",format:"One integer n. Output: true or false.",hint:"A power of two has exactly one set bit in its binary representation.",approach:"Check n > 0 and n & (n−1) == 0. O(1) time.",tests:[{input:"1\n",output:"true"},{input:"16\n",output:"true"},{input:"3\n",output:"false"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();System.out.println(n>0&&(n&(n-1))==0);}}`},
{id:"longest-consecutive",topic:"Arrays",title:"Longest Consecutive Sequence",difficulty:"Medium",description:"Find the length of the longest sequence of consecutive integer values in an unsorted array. The values do not need to be adjacent in the array.",format:"Line 1: n. Line 2: n integers. Output: sequence length.",hint:"Only start counting from a value whose predecessor is absent from the set.",approach:"Hash set membership gives O(n) expected time and O(n) space.",tests:[{input:"6\n100 4 200 1 3 2\n",output:"4"},{input:"9\n0 3 7 2 5 8 4 6 0\n",output:"7"},{input:"0\n\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();Set<Integer>a=new HashSet<>();for(int i=0;i<n;i++)a.add(s.nextInt());int b=0;for(int v:a)if(!a.contains(v-1)){int c=v;while(a.contains(c))c++;b=Math.max(b,c-v);}System.out.println(b);}}`},
{id:"second-largest",topic:"Arrays",title:"Second Largest Distinct Value",difficulty:"Easy",description:"Return the second largest distinct value in an integer array, or -1 if no such value exists.",format:"Line 1: n. Line 2: n integers. Output: second distinct maximum or -1.",hint:"Track the largest and second-largest distinct values as you scan.",approach:"Single pass with two variables. O(n) time and O(1) space.",tests:[{input:"6\n12 35 1 10 34 1\n",output:"34"},{input:"3\n10 10 10\n",output:"-1"},{input:"2\n-5 -1\n",output:"-5"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();long a=Long.MIN_VALUE,b=Long.MIN_VALUE;for(int i=0;i<n;i++){long v=s.nextInt();if(v>a){b=a;a=v;}else if(v<a&&v>b)b=v;}System.out.println(b==Long.MIN_VALUE?-1:b);}}`},
{id:"array-is-sorted",topic:"Arrays",title:"Check if Array Is Sorted",difficulty:"Easy",description:"Determine whether the integer array is sorted in non-decreasing order.",format:"Line 1: n. Line 2: n integers. Output: true or false.",hint:"Compare each value to the one immediately before it.",approach:"Single scan. O(n) time and O(1) space.",tests:[{input:"5\n1 2 2 4 5\n",output:"true"},{input:"3\n1 3 2\n",output:"false"},{input:"1\n7\n",output:"true"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();boolean ok=true,has=false;int p=0;for(int i=0;i<n;i++){int v=s.nextInt();if(has&&p>v)ok=false;p=v;has=true;}System.out.println(ok);}}`},
{id:"linear-search",topic:"Arrays",title:"Linear Search",difficulty:"Easy",description:"Return the first zero-based index of target in the array, or -1 if it does not occur.",format:"Line 1: n target. Line 2: n integers. Output: first index or -1.",hint:"Scan from left to right and stop at the first match.",approach:"Linear scan. O(n) time and O(1) space.",tests:[{input:"5 4\n1 2 4 4 5\n",output:"2"},{input:"3 9\n1 2 3\n",output:"-1"},{input:"1 7\n7\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),t=s.nextInt(),z=-1;for(int i=0;i<n;i++){int v=s.nextInt();if(v==t&&z<0)z=i;}System.out.println(z);}}`},
{id:"sum-array",topic:"Arrays",title:"Sum of Array Elements",difficulty:"Easy",description:"Compute the sum of all values in the array. The sum fits in a signed 64-bit integer.",format:"Line 1: n. Line 2: n integers. Output: sum.",hint:"Use a 64-bit accumulator so intermediate totals do not overflow a 32-bit integer.",approach:"Single pass accumulation. O(n) time and O(1) space.",tests:[{input:"5\n1 2 3 4 5\n",output:"15"},{input:"3\n-1 -2 3\n",output:"0"},{input:"0\n\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();long z=0;for(int i=0;i<n;i++)z+=s.nextInt();System.out.println(z);}}`},
{id:"gcd",topic:"Math",title:"Greatest Common Divisor",difficulty:"Easy",description:"Find the greatest common divisor of two non-negative integers using the Euclidean algorithm.",format:"Two non-negative integers a b. Output: gcd(a,b).",hint:"Replace (a,b) with (b,a mod b) until the second value is zero.",approach:"Euclidean algorithm. O(log min(a,b)) time and O(1) space.",tests:[{input:"48 18\n",output:"6"},{input:"7 13\n",output:"1"},{input:"0 9\n",output:"9"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int a=s.nextInt(),b=s.nextInt();while(b!=0){int t=a%b;a=b;b=t;}System.out.println(a);}}`},
{id:"factorial",topic:"Math",title:"Factorial",difficulty:"Easy",description:"Compute n! for 0 ≤ n ≤ 20. By definition, 0! equals 1.",format:"One integer n. Output: n!.",hint:"Multiply the integers from 2 through n; initialize the product to 1.",approach:"Iterative multiplication. O(n) time and O(1) space.",tests:[{input:"5\n",output:"120"},{input:"0\n",output:"1"},{input:"1\n",output:"1"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();long z=1;for(int i=2;i<=n;i++)z*=i;System.out.println(z);}}`},
{id:"sum-digits",topic:"Math",title:"Sum of Digits",difficulty:"Easy",description:"Return the sum of the decimal digits of the absolute value of an integer.",format:"One signed integer n. Output: digit sum.",hint:"Repeatedly take n modulo 10 and divide n by 10.",approach:"Digit-by-digit loop. O(number of digits) time and O(1) space.",tests:[{input:"12345\n",output:"15"},{input:"-99\n",output:"18"},{input:"0\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);long n=Math.abs(s.nextLong());int z=0;while(n>0){z+=n%10;n/=10;}System.out.println(z);}}`},
{id:"reverse-array",topic:"Arrays",title:"Reverse an Array",difficulty:"Easy",description:"Reverse the order of all array elements in place and print the result.",format:"Line 1: n. Line 2: n integers. Output: reversed values separated by spaces.",hint:"Swap the first and last values, then move both pointers inward.",approach:"Two-pointer in-place reversal. O(n) time and O(1) extra space.",tests:[{input:"5\n1 2 3 4 5\n",output:"5 4 3 2 1"},{input:"4\n1 2 3 4\n",output:"4 3 2 1"},{input:"1\n9\n",output:"9"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();for(int l=0,r=n-1;l<r;l++,r--){int t=a[l];a[l]=a[r];a[r]=t;}StringJoiner j=new StringJoiner(" ");for(int v:a)j.add(""+v);System.out.println(j);}}`},
{id:"min-max-array",topic:"Arrays",title:"Find Minimum and Maximum",difficulty:"Easy",description:"Find the minimum and maximum values in a non-empty integer array.",format:"Line 1: n. Line 2: n integers. Output: minimum maximum.",hint:"Initialize both values from the first element and update them in one scan.",approach:"Single pass. O(n) time and O(1) extra space.",tests:[{input:"5\n3 1 9 -2 7\n",output:"-2 9"},{input:"1\n4\n",output:"4 4"},{input:"3\n-1 -8 -3\n",output:"-8 -1"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),lo=s.nextInt(),hi=lo;for(int i=1;i<n;i++){int v=s.nextInt();lo=Math.min(lo,v);hi=Math.max(hi,v);}System.out.println(lo+" "+hi);}}`},
{id:"count-even",topic:"Arrays",title:"Count Even Numbers",difficulty:"Easy",description:"Count how many array values are even. Negative even numbers count as even.",format:"Line 1: n. Line 2: n integers. Output: even-value count.",hint:"An integer is even when its remainder modulo 2 is zero.",approach:"Single scan. O(n) time and O(1) space.",tests:[{input:"6\n1 2 3 4 5 6\n",output:"3"},{input:"3\n-2 -3 0\n",output:"2"},{input:"1\n7\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),z=0;for(int i=0;i<n;i++)if(s.nextInt()%2==0)z++;else{}System.out.println(z);}}`},
{id:"remove-element",topic:"Arrays",title:"Remove Element",difficulty:"Easy",description:"Remove all occurrences of target in place while preserving the order of remaining values. Print the new length and remaining prefix.",format:"Line 1: n target. Line 2: n integers. Output: k, then k remaining values.",hint:"Use a write pointer and copy only values that differ from target.",approach:"Stable compaction. O(n) time and O(1) extra space.",tests:[{input:"5 3\n3 2 2 3 4\n",output:"3\n2 2 4"},{input:"4 2\n2 2 2 2\n",output:"0\n"},{input:"3 9\n1 2 3\n",output:"3\n1 2 3"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),t=s.nextInt(),k=0;int[]a=new int[n];for(int i=0;i<n;i++){int v=s.nextInt();if(v!=t)a[k++]=v;}System.out.println(k);for(int i=0;i<k;i++){if(i>0)System.out.print(" ");System.out.print(a[i]);}}}`},
{id:"sorted-squares",topic:"Arrays",title:"Squares of a Sorted Array",difficulty:"Easy",description:"Given a non-decreasing array that may contain negative numbers, return the squares in non-decreasing order.",format:"Line 1: n. Line 2: n sorted integers. Output: sorted squares.",hint:"The largest square must come from one of the two ends; fill the output from right to left.",approach:"Two pointers. O(n) time and O(n) output space.",tests:[{input:"5\n-4 -1 0 3 10\n",output:"0 1 9 16 100"},{input:"5\n-7 -3 2 3 11\n",output:"4 9 9 49 121"},{input:"1\n-2\n",output:"4"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n],o=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();int l=0,r=n-1;for(int k=n-1;k>=0;k--){int u=a[l]*a[l],v=a[r]*a[r];if(u>v){o[k]=u;l++;}else{o[k]=v;r--;}}StringJoiner j=new StringJoiner(" ");for(int v:o)j.add(""+v);System.out.println(j);}}`},
{id:"number-steps-zero",topic:"Bit Manipulation",title:"Number of Steps to Reduce a Number to Zero",difficulty:"Easy",description:"For an integer n, repeatedly divide by 2 when even and subtract 1 when odd. Return the number of operations needed to reach zero.",format:"One non-negative integer n. Output: number of operations.",hint:"Simulate the rule, or count the bits: each set bit needs a subtraction and each remaining shift needs a division.",approach:"Bit counting gives O(log n) time. A direct loop is also linear in bit length.",tests:[{input:"14\n",output:"6"},{input:"8\n",output:"4"},{input:"0\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),z=0;while(n>0){z++;if((n&1)==0)n>>=1;else n--;}System.out.println(z);}}`},
{id:"is-power-of-three",topic:"Math",title:"Power of Three",difficulty:"Easy",description:"Determine whether a positive integer is an exact power of three.",format:"One integer n. Output: true or false.",hint:"Repeatedly divide by 3 while the value is divisible; check whether it ends at 1.",approach:"Repeated division. O(log n) time and O(1) space.",tests:[{input:"27\n",output:"true"},{input:"0\n",output:"false"},{input:"45\n",output:"false"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();if(n>0)while(n%3==0)n/=3;System.out.println(n==1);}}`},
{id:"climbing-stairs-ways",topic:"Dynamic Programming",title:"Minimum Jumps to Reach End",difficulty:"Medium",description:"Each value indicates the maximum forward jump length from that index. Return the fewest jumps needed to reach the final index; return -1 if unreachable.",format:"Line 1: n. Line 2: n non-negative values. Output: minimum jumps or -1.",hint:"Track the current jump boundary and the farthest index reachable in the next jump.",approach:"Greedy breadth layers. O(n) time and O(1) space.",tests:[{input:"5\n2 3 1 1 4\n",output:"2"},{input:"5\n3 2 1 0 4\n",output:"-1"},{input:"1\n0\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();if(n<=1){System.out.println(0);return;}int jumps=0,end=0,far=0;for(int i=0;i<n-1;i++){far=Math.max(far,i+a[i]);if(i==end){if(far==end){System.out.println(-1);return;}jumps++;end=far;}}System.out.println(jumps);}}`},
{id:"range-sum-queries",topic:"Arrays",title:"Range Sum Queries",difficulty:"Easy",description:"Answer q inclusive range-sum queries on an immutable integer array. Each query gives left and right zero-based indices.",format:"Line 1: n q. Line 2: n integers. Next q lines: l r. Output one sum per query.",hint:"Build prefix sums once. A range sum is prefix[r+1] − prefix[l].",approach:"Prefix sums. O(n+q) time and O(n) space.",tests:[{input:"5 3\n1 2 3 4 5\n0 2\n1 3\n0 4\n",output:"6\n9\n15"},{input:"1 1\n-3\n0 0\n",output:"-3"},{input:"3 1\n5 0 5\n1 1\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),q=s.nextInt();long[]p=new long[n+1];for(int i=0;i<n;i++)p[i+1]=p[i]+s.nextInt();StringBuilder o=new StringBuilder();while(q-->0){int l=s.nextInt(),r=s.nextInt();if(o.length()>0)o.append('\\n');o.append(p[r+1]-p[l]);}System.out.print(o);}}`},
{id:"good-pairs",topic:"Hashing",title:"Number of Good Pairs",difficulty:"Easy",description:"A pair (i,j) is good when i < j and nums[i] == nums[j]. Count all good pairs.",format:"Line 1: n. Line 2: n integers. Output: pair count.",hint:"When a value appears again, it forms one new pair with every previous occurrence.",approach:"Frequency map in one pass. O(n) average time and O(k) space.",tests:[{input:"6\n1 2 3 1 1 3\n",output:"4"},{input:"3\n1 1 1\n",output:"3"},{input:"3\n1 2 3\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),z=0;Map<Integer,Integer>m=new HashMap<>();for(int i=0;i<n;i++){int v=s.nextInt(),c=m.getOrDefault(v,0);z+=c;m.put(v,c+1);}System.out.println(z);}}`},
{id:"can-place-flowers",topic:"Greedy",title:"Can Place Flowers",difficulty:"Easy",description:"Given a flowerbed where adjacent plots cannot both hold flowers, determine whether n additional flowers can be planted without violating the rule.",format:"Line 1: length m and n. Line 2: m zero-or-one values. Output: true or false.",hint:"Greedily plant at an empty plot when both neighbours are empty or outside the flowerbed.",approach:"Single greedy scan. O(m) time and O(1) extra space.",tests:[{input:"5 1\n1 0 0 0 1\n",output:"true"},{input:"5 2\n1 0 0 0 1\n",output:"false"},{input:"1 1\n0\n",output:"true"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int m=s.nextInt(),n=s.nextInt(),z=0;int[]a=new int[m];for(int i=0;i<m;i++)a[i]=s.nextInt();for(int i=0;i<m;i++)if(a[i]==0&&(i==0||a[i-1]==0)&&(i==m-1||a[i+1]==0)){a[i]=1;z++;}System.out.println(z>=n);}}`},
{id:"last-stone-weight",topic:"Heaps",title:"Last Stone Weight",difficulty:"Easy",description:"Repeatedly smash the two heaviest stones. If they differ, put their positive difference back. Return the final stone weight or 0.",format:"Line 1: n. Line 2: n positive weights. Output: final weight.",hint:"A max-heap gives quick access to the two heaviest remaining stones.",approach:"Max-priority queue. O(n log n) time and O(n) space.",tests:[{input:"6\n2 7 4 1 8 1\n",output:"1"},{input:"1\n2\n",output:"2"},{input:"2\n3 3\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();PriorityQueue<Integer>q=new PriorityQueue<>(Collections.reverseOrder());for(int i=0;i<n;i++)q.add(s.nextInt());while(q.size()>1){int a=q.poll(),b=q.poll();if(a!=b)q.add(a-b);}System.out.println(q.isEmpty()?0:q.poll());}}`},
{id:"minimum-depth-tree",topic:"Trees",title:"Minimum Depth of Binary Tree",difficulty:"Easy",description:"Find the number of nodes on the shortest root-to-leaf path in a binary tree represented by complete-array slots; -1 marks absent nodes.",format:"Line 1: slot count n. Line 2: n values. Output: minimum depth (0 for an empty tree).",hint:"Use BFS: the first leaf reached is the shallowest. Do not treat a missing child as a leaf when its sibling exists.",approach:"BFS by level over child indices. O(n) time and O(width) space.",tests:[{input:"7\n3 9 20 -1 -1 15 7\n",output:"2"},{input:"1\n1\n",output:"1"},{input:"0\n\n",output:"0"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n];for(int i=0;i<n;i++)a[i]=s.nextInt();if(n==0||a[0]==-1){System.out.println(0);return;}Queue<int[]>q=new ArrayDeque<>();q.add(new int[]{0,1});int ans=0;while(!q.isEmpty()){int[]p=q.remove();int i=p[0],d=p[1],l=2*i+1,r=l+1;boolean hasL=l<n&&a[l]!=-1,hasR=r<n&&a[r]!=-1;if(!hasL&&!hasR){ans=d;break;}if(hasL)q.add(new int[]{l,d+1});if(hasR)q.add(new int[]{r,d+1});}System.out.println(ans);}}`},
{id:"contains-nearby-duplicate",topic:"Hashing",title:"Contains Duplicate II",difficulty:"Easy",description:"Determine whether there are two equal values whose indices differ by at most k.",format:"Line 1: n k. Line 2: n integers. Output: true or false.",hint:"Store each value’s most recent index and compare the distance when it appears again.",approach:"Hash map scan. O(n) average time and O(n) space.",tests:[{input:"4 3\n1 2 3 1\n",output:"true"},{input:"4 2\n1 2 3 1\n",output:"false"},{input:"6 1\n1 0 1 1 0 1\n",output:"true"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt(),k=s.nextInt();Map<Integer,Integer>m=new HashMap<>();boolean ok=false;for(int i=0;i<n;i++){int v=s.nextInt();if(m.containsKey(v)&&i-m.get(v)<=k)ok=true;m.put(v,i);}System.out.println(ok);}}`},
{id:"stock-span",topic:"Stacks",title:"Stock Span Problem",difficulty:"Medium",description:"For each day, compute the number of consecutive days up to that day for which the price was less than or equal to today’s price.",format:"Line 1: n. Line 2: n prices. Output: n span values.",hint:"Maintain indices of previous prices that are strictly greater than the current price.",approach:"Monotonic decreasing stack. O(n) time and O(n) space.",tests:[{input:"7\n100 80 60 70 60 75 85\n",output:"1 1 1 2 1 4 6"},{input:"3\n10 20 30\n",output:"1 2 3"},{input:"4\n40 30 20 10\n",output:"1 1 1 1"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);int n=s.nextInt();int[]a=new int[n],o=new int[n];Deque<Integer>d=new ArrayDeque<>();for(int i=0;i<n;i++){a[i]=s.nextInt();while(!d.isEmpty()&&a[d.peek()]<=a[i])d.pop();o[i]=d.isEmpty()?i+1:i-d.peek();d.push(i);}StringJoiner j=new StringJoiner(" ");for(int v:o)j.add(""+v);System.out.println(j);}}`},
{id:"pangram",topic:"Strings",title:"Check Pangram",difficulty:"Easy",description:"Determine whether a sentence contains every English letter a through z at least once, ignoring case and punctuation.",format:"One full input line. Output: true or false.",hint:"Track letters in a 26-element boolean array and check whether all were seen.",approach:"Single scan over the sentence. O(n) time and O(1) space.",tests:[{input:"The quick brown fox jumps over the lazy dog\n",output:"true"},{input:"Hello world\n",output:"false"},{input:"abcdefghijklmnopqrstuvwxyz\n",output:"true"}],solution:`import java.util.*;class Main{public static void main(String[]x){Scanner s=new Scanner(System.in);String a=s.hasNextLine()?s.nextLine().toLowerCase():"";boolean[]v=new boolean[26];for(char c:a.toCharArray())if(c>='a'&&c<='z')v[c-'a']=true;boolean ok=true;for(boolean b:v)ok&=b;System.out.println(ok);}}`},
];
const TRACK_KEY="arenaDsaProgress:v3";
const getProgress=(language)=>{try{return JSON.parse(localStorage.getItem(`${TRACK_KEY}:${language||"java"}`)||(language==="java"?localStorage.getItem("arenaDsaProgress:v2"):null)||"{}");}catch{return {};}};
const acceptedCodeKey=(language,id)=>`dsaAcceptedCode:${language}:${id}`;
const acceptedResultsKey=(language,id)=>`dsaAcceptedResults:${language}:${id}`;
const getLanguage=()=>localStorage.getItem("studyPlanLanguage")||"";

function DSASheet({onNavigate}){
 const [access,setAccess]=useState(null),[topic,setTopic]=useState("All topics"),[difficulty,setDifficulty]=useState("All levels"),[query,setQuery]=useState(""),[selectedId,setSelectedId]=useState(QUESTIONS[0].id),[problemOpen,setProblemOpen]=useState(false),[panel,setPanel]=useState(""),[progress,setProgress]=useState(()=>getProgress(getLanguage())),[language,setLanguage]=useState(getLanguage),[languageReady,setLanguageReady]=useState(false),[code,setCode]=useState(""),[runnerReady,setRunnerReady]=useState(false),[runnerMessage,setRunnerMessage]=useState(""),[running,setRunning]=useState(false),[results,setResults]=useState([]),[error,setError]=useState(""),[runtime,setRuntime]=useState("");
 const question=QUESTIONS.find(q=>q.id===selectedId)||QUESTIONS[0];
 const topicNames=["All topics",...new Set(QUESTIONS.map(q=>q.topic))];
 const filtered=useMemo(()=>QUESTIONS.filter(q=>(topic==="All topics"||q.topic===topic)&&(difficulty==="All levels"||q.difficulty===difficulty)&&(!query||q.title.toLowerCase().includes(query.toLowerCase()))),[topic,difficulty,query]);
 const doneCount=Object.keys(progress).filter(id=>progress[id]).length;
 useEffect(()=>{const token=localStorage.getItem("token");if(!token){setAccess({isActive:false});return;}fetch(`${API_URL}/api/payments/subscription`,{headers:{Authorization:`Bearer ${token}`}}).then(r=>r.ok?r.json():Promise.reject()).then(setAccess).catch(()=>setAccess({isActive:false,error:true}));fetch(`${API_URL}/api/code/runtimes`,{headers:{Authorization:`Bearer ${token}`}}).then(r=>r.ok?r.json():Promise.reject()).then(d=>{const runtime=d.languages?.find(item=>item.id===language);setRunnerReady(Boolean(d.configured&&runtime?.available));setRunnerMessage(d.message||(runtime&&!runtime.available?`${LANGS[language]?.label||language} compiler is currently unavailable.`:""));}).catch(()=>{setRunnerReady(false);setRunnerMessage("Compiler is temporarily unavailable.");});},[language]);
 useEffect(()=>{const token=localStorage.getItem("token");if(!token){setLanguage("");setLanguageReady(true);return;}fetch(`${API_URL}/api/auth/me`,{headers:{Authorization:`Bearer ${token}`}}).then(r=>r.ok?r.json():Promise.reject()).then(d=>{const savedLanguage=d.user?.studyPlanLanguage;if(savedLanguage&&LANGS[savedLanguage]){setLanguage(savedLanguage);localStorage.setItem("studyPlanLanguage",savedLanguage);}else{setLanguage("");localStorage.removeItem("studyPlanLanguage");}}).catch(()=>{}).finally(()=>setLanguageReady(true));},[]);
 useEffect(()=>{const key=`dsaFunctionCode:${language}:${question.id}`;const saved=localStorage.getItem(key)||(language==="java"?localStorage.getItem(`dsaFunctionCode:${question.id}`):null);let nextCode="";if(language==="java"){const normalized=saved?normalizeJavaDraftForQuestion(question,saved):"";if(normalized&&isJavaDraftForQuestion(question,normalized)){nextCode=normalized;if(normalized!==saved||!localStorage.getItem(key))localStorage.setItem(key,normalized);}else nextCode=buildJavaTemplate(question);}else if(language==="cpp")nextCode=saved||buildCppTemplate(question);else if(language==="python")nextCode=saved||buildPythonTemplate(question);setCode(nextCode);setProgress(getProgress(language));try{const acceptedCode=localStorage.getItem(acceptedCodeKey(language,question.id));const priorResults=JSON.parse(localStorage.getItem(acceptedResultsKey(language,question.id))||"[]");setResults(acceptedCode===nextCode?priorResults:[]);}catch{setResults([]);}setError("");},[question.id,language]);
 const updateCode=(nextCode)=>{setCode(nextCode);localStorage.setItem(`dsaFunctionCode:${language}:${question.id}`,nextCode);if(localStorage.getItem(acceptedCodeKey(language,question.id))!==nextCode){const nextProgress={...getProgress(language)};delete nextProgress[question.id];setProgress(nextProgress);localStorage.setItem(`${TRACK_KEY}:${language}`,JSON.stringify(nextProgress));localStorage.removeItem(acceptedCodeKey(language,question.id));localStorage.removeItem(acceptedResultsKey(language,question.id));setResults([]);}};
 const runTests=async()=>{setError("");setResults([]);if(!runnerReady){setError(runnerMessage||"Compiler is not connected.");return;}if(!code.trim()){setError("Write your solution before running tests.");return;}setRunning(true);try{const r=await fetch(`${API_URL}/api/code/run-tests`,{method:"POST",headers:{"Content-Type":"application/json",Authorization:`Bearer ${localStorage.getItem("token")}`},body:JSON.stringify({language,code,testCases:question.tests})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.message||"Could not run test cases.");const nextResults=d.results||[];setResults(nextResults);setRuntime(d.runtime||"");if(d.accepted&&d.passedCount===3){const next={...progress,[question.id]:true};setProgress(next);localStorage.setItem(`${TRACK_KEY}:${language}`,JSON.stringify(next));localStorage.setItem(acceptedCodeKey(language,question.id),code);localStorage.setItem(acceptedResultsKey(language,question.id),JSON.stringify(nextResults));} }catch(e){setError(e.message||"Could not reach compiler.");}finally{setRunning(false);}};
 if(access===null)return <main className="dsa-page"><section className="dsa-gate"><h1>Checking DSA Sheet access…</h1></section></main>;
 if(!access.isActive&&!access.isPaymentAdmin)return <main className="dsa-page"><section className="dsa-gate"><span>🔒</span><p className="dsa-eyebrow">DSA PRACTICE SHEET</p><h1>Unlock the DSA practice sheet</h1><p>Active Study Plan access is needed to open the problem bank. After access is approved, return here to practise.</p><button onClick={()=>onNavigate?.("study-plan")}>Go to Study Plan →</button></section></main>;
 if(!languageReady)return <main className="dsa-page"><section className="dsa-gate"><h1>Loading your saved language…</h1></section></main>;
 if(!language)return <main className="dsa-page"><section className="dsa-gate"><span>⌘</span><p className="dsa-eyebrow">CHOOSE YOUR LANGUAGE</p><h1>Set up your Study Plan first</h1><p>Choose your programming language in Study Plan before opening the DSA practice sheet.</p><button onClick={()=>onNavigate?.("study-plan")}>Choose language →</button></section></main>;
 if(!LANGS[language])return <main className="dsa-page"><section className="dsa-gate"><span>⌘</span><p className="dsa-eyebrow">LANGUAGE VERSIONS</p><h1>That DSA language version is not ready yet</h1><p>Java, C++, and Python have separate question templates. JavaScript and C# versions are still being prepared.</p><button onClick={()=>onNavigate?.("study-plan")}>Back to Study Plan →</button></section></main>;
 return <main className="dsa-page"><header className="dsa-hero"><div><p className="dsa-eyebrow">INTERVIEW PRACTICE · DSA SHEET</p><h1>Practise DSA, one problem at a time.</h1><p>Choose a problem to open its own {LANGS[language].label} function workspace. The test runner is locked; write the solution and any helper methods.</p></div><div className="dsa-progress-card"><span>ACCEPTED · {LANGS[language].label.toUpperCase()}</span><strong>{doneCount}<small> / {QUESTIONS.length}</small></strong><div><i style={{width:`${doneCount/QUESTIONS.length*100}%`}}/></div><small>Tick appears only after all 3 tests pass</small></div></header>
 {!problemOpen?<div className="dsa-layout"><aside className="dsa-topics"><p className="dsa-eyebrow">TOPICS</p>{topicNames.map(t=><button key={t} className={topic===t?"is-active":""} onClick={()=>setTopic(t)}>{t}<span>{t==="All topics"?QUESTIONS.length:QUESTIONS.filter(q=>q.topic===t).length}</span></button>)}</aside>
 <section className="dsa-list-panel"><div className="dsa-list-heading"><div><h2>{topic}</h2><p>{filtered.length} curated questions · progress is saved on this device</p></div><div className="dsa-filters"><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search problems" aria-label="Search DSA problems"/><select value={difficulty} onChange={e=>setDifficulty(e.target.value)} aria-label="Difficulty"><option>All levels</option><option>Easy</option><option>Medium</option><option>Hard</option></select></div></div><div className="dsa-question-list">{filtered.map(q=><button key={q.id} className={`dsa-question-row${q.id===question.id?" is-selected":""}`} onClick={()=>{setSelectedId(q.id);setPanel("");setProblemOpen(true);}}><span className="dsa-number">{String(QUESTIONS.indexOf(q)+1).padStart(2,"0")}</span><span className="dsa-q-title"><strong>{q.title}</strong><small>{q.topic}</small></span><span className={`dsa-difficulty is-${q.difficulty.toLowerCase()}`}>{q.difficulty}</span><span className={`dsa-done-mark${progress[q.id]?" is-done":""}`}>{progress[q.id]?"✓":"›"}</span></button>)}</div></section></div>:<>
 <div className="dsa-open-toolbar"><button onClick={()=>setProblemOpen(false)}>← All questions</button><div><span>Problem {QUESTIONS.indexOf(question)+1} of {QUESTIONS.length}</span><button disabled={QUESTIONS.indexOf(question)===0} onClick={()=>{setSelectedId(QUESTIONS[QUESTIONS.indexOf(question)-1].id);setPanel("");}}>← Previous</button><button disabled={QUESTIONS.indexOf(question)===QUESTIONS.length-1} onClick={()=>{setSelectedId(QUESTIONS[QUESTIONS.indexOf(question)+1].id);setPanel("");}}>Next →</button></div></div>
 <div className="dsa-open-layout"><section className="dsa-problem-pane"><div className="dsa-challenge-heading"><div><p className="dsa-eyebrow">PROBLEM {String(QUESTIONS.indexOf(question)+1).padStart(2,"0")} · {question.topic.toUpperCase()}</p><h2>{question.title}</h2><span className={`dsa-difficulty is-${question.difficulty.toLowerCase()}`}>{question.difficulty}</span></div><span className={`dsa-accepted${progress[question.id]?" is-done":""}`}>{progress[question.id]?"✓ Accepted · 3/3":"Not completed"}</span></div><p className="dsa-problem-text">{question.description}</p><div className="dsa-format"><strong>Input / output</strong><p>{question.format}</p></div><div className="dsa-example"><strong>Example input</strong><pre>{question.tests[0].input.trim()||"(empty)"}</pre><strong>Expected output</strong><pre>{question.tests[0].output||"(empty)"}</pre></div>
 <div className="dsa-help-row"><button onClick={()=>setPanel(panel==="hint"?"":"hint")}>💡 {panel==="hint"?"Hide hint":"Hint"}</button><button onClick={()=>setPanel(panel==="approach"?"":"approach")}>▤ {panel==="approach"?"Hide approach":"Approach"}</button>{language==="java"&&<button onClick={()=>setPanel(panel==="solution"?"":"solution")}>⌘ {panel==="solution"?"Hide answer":"Answer"}</button>}</div>{panel&&<div className="dsa-approach"><strong>{panel==="hint"?"Hint":panel==="solution"?"Reference solution · Java":"Suggested approach"}</strong><p>{panel==="hint"?question.hint:panel==="approach"?question.approach:"Readable Java function and any helper methods for this exact problem."}</p>{panel==="solution"&&<pre>{buildJavaTemplate(question,{answer:true})}</pre>}</div>}</section>
 <section className="dsa-workspace-card"><div className="dsa-editor-toolbar"><label className="dsa-language-static">Language <strong>{LANGS[language].label}</strong><small>Fixed to your Study Plan</small></label><button onClick={runTests} disabled={running||!runnerReady}>{running?"Running tests…":"▶ Run 3 tests"}</button></div><div className="dsa-editor-title"><span className="dsa-live-dot"/>{question.title.replace(/[^a-z0-9]/gi,"")}.{LANGS[language].ext}<small>{runnerReady?(runtime||"Online compiler ready"):runnerMessage||"Connecting compiler…"}</small><small className="dsa-lock-label">Function body + helper methods editable · runner locked</small></div><CodeEditor key={`${question.id}:${language}`} language={language} value={code} onChange={updateCode} onRun={runTests} ariaLabel={`${LANGS[language].label} function editor`} className="dsa-code-editor" lockOutsideSolution/><div className="dsa-results"><div className="dsa-results-heading"><strong>Test results</strong><span>{results.length?`${results.filter(r=>r.accepted).length}/3 passed`:"3 test cases"}</span></div>{error&&<p className="dsa-run-error">{error}</p>}{results.length===0&&!error&&<p className="dsa-results-empty">{progress[question.id]?"Accepted earlier. Run tests to refresh the case details.":"Run tests to check your solution against the three examples."}</p>}{results.map(r=><article className={`dsa-case${r.accepted?" is-pass":" is-fail"}`} key={r.caseNumber}><strong>{r.accepted?"✓":"×"} Case {r.caseNumber} · {r.status}</strong>{!r.accepted&&<div><span>Expected</span><pre>{r.expectedOutput||"(empty)"}</pre><span>Your output</span><pre>{r.actualOutput||r.compileOutput||r.stderr||"(empty)"}</pre></div>}</article>)}{results.length===3&&results.every(r=>r.accepted)&&<p className="dsa-all-accepted">✓ Accepted · all three tests passed</p>}</div></section></div></>}
 </main>;
}
export default DSASheet;
